/** Auto-generated for round 58 */
export const QUIZ_ITEMS = [
  { id: "1715", section: "الفرائض والمواريث", category: "المواريث", level: "متوسط", question: "ما موانع الإرث الثلاثة في الفقه الإسلامي؟", answer: "ثلاثة: 1- القتل العمد العدوان (القاتل لا يرث ممن قتله). 2- اختلاف الدين (المسلم لا يرث الكافر ولا الكافر المسلم بالإجماع). 3- الرق (العبد لا يرث ولا يُورَث في حكمه).", explanation: "يُستفاد منه في باب المواريث. يُستفاد منه في باب المواريث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1716", section: "الفرائض والمواريث", category: "الفروض", level: "صعب", question: "كم فريضة حددها القرآن الكريم في المواريث؟", answer: "ستة فروض مقدّرة: النصف (1/2)، الربع (1/4)، الثمن (1/8)، الثلثان (2/3)، الثلث (1/3)، السدس (1/6) — وكل منها لمستحق محدد بآيات النساء (11-12 و176).", explanation: "يُستفاد منه في باب الفروض. يُستفاد منه في باب الفروض مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1717", section: "الفرائض والمواريث", category: "الحجب", level: "صعب", question: "ما الفرق بين حجب الحرمان وحجب النقصان؟", answer: "حجب الحرمان: حجب الوارث كلياً عن الإرث — كحجب الأخ بالابن. حجب النقصان: نقل الوارث من فرض أعلى إلى أدنى — كانتقال الزوج من النصف (1/2) إلى الربع (1/4) عند وجود الولد.", explanation: "يُستفاد منه في باب الحجب. يُستفاد منه في باب الحجب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1718", section: "الفرائض والمواريث", category: "أصحاب الفروض", level: "متوسط", question: "من الورثة الذين لا يُحجبون حجب حرمان أبداً؟", answer: "ستة: الأب، الأم، الابن، البنت، الزوج، الزوجة — لا يُحجبون حجب حرمان مطلقاً وإن نقص نصيبهم بحجب النقصان (كانتقال الزوج من النصف إلى الربع عند وجود الولد). أما ابن الابن (الحفيد) فليس منهم؛ إذ يُحجب حجب حرمان تاماً بوجود الابن.", explanation: "يُستفاد منه في باب أصحاب الفروض. يُستفاد منه في باب أصحاب الفروض مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1719", section: "الفرائض والمواريث", category: "الوصية", level: "متوسط", question: "ما أقصى ما يجوز للمسلم إيصاء به من ماله؟", answer: "لا تجوز الوصية بأكثر من ثلث المال للأجانب — لحديث سعد رضي الله عنه: «الثلث والثلث كثير» (البخاري). ولا تجوز الوصية لوارث ألبتة إلا بإجازة بقية الورثة.", explanation: "يُستفاد منه في باب الوصية. يُستفاد منه في باب الوصية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1720", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من هم أصحاب الفروض المحددة في القرآن؟", answer: "أصحاب الفروض المقدَّرة في القرآن: 1) الزوج: النصف أو الربع. 2) الزوجة/الزوجات: الربع أو الثمن. 3) الأم: الثلث أو السدس. 4) الأب: السدس (عصبة). 5) البنت/البنات: النصف أو الثلثان. 6) الأخت الشقيقة: النصف أو الثلثان. 7) الجدة: السدس. 8) الأخ لأم والأخت لأم: السدس أو الثلث.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1721", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من الذين يُحجَبون حجب حرمان من الميراث؟ اذكر أمثلة.", answer: "حجب الحرمان: حرمان الوارث من الإرث بسبب وجود وارث أقوى منه. أمثلة: 1) الجد يُحجَب بوجود الأب. 2) الإخوة يُحجَبون بوجود الابن أو الأب. 3) بنت الابن تُحجَب بوجود بنتين فأكثر إلا إذا وُجد معها ابن ابن. 4) الأخت لأم تُحجَب بوجود الفرع الوارث أو الأصل الذكر. والمانعون من الإرث: الكفر، والقتل العمد، والرق.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1722", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما الفرق بين اسمَي الله «الغفور» و«الغفّار»؟", answer: "الغفور: يدل على سعة المغفرة في ذاتها مهما عظمت الذنوب. الغفّار: يدل على كثرة المغفرة وتكرارها مراراً وتكراراً، أي كثير المغفرة لا ينضب عفوه. والاسمان معاً يُعطيان المؤمن رجاءً بسعة المغفرة واستمرارها مهما كان العبد مذنباً وكثُرت عودته بالتوبة.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1723", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "سهل", question: "ما معنى اسم الله «الحليم» وكيف يُفرَّق بينه وبين الصبور؟", answer: "الحليم: الذي لا يستفزه عصيان العصاة ولا يُقلقه انتشار المعاصي، فيؤخر العقوبة رحمةً وحكمةً. الصبور في المقابل: يركز على التأخير الطويل مع الإحاطة بالخلق. الحليم يُشير إلى الطمأنينة التامة وعدم تغيّر حال الله بمعصية عبده.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1724", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما معنى اسمَي الله «الوكيل» و«الكفيل»؟", answer: "الوكيل: الذي يتولى مصالح عباده ويكفيهم ما يهمهم. قال تعالى: ﴿وَكَفَىٰ بِاللَّهِ وَكِيلاً﴾. ومعناه التفويض التام إليه والاعتماد عليه وحده في جلب المصالح ودرء المفاسد. وهو ضمنياً يتضمن الكفالة والرعاية الكاملة لمن توكل عليه.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1725", section: "الأسماء الحسنى", category: "الأسماء الحسنى عموماً", level: "سهل", question: "كم اسماً من أسماء الله الحسنى وردت في الحديث المشهور عند الترمذي وابن ماجه؟", answer: "تسعة وتسعون اسماً في حديث: «إن لله تسعة وتسعين اسماً مئةً إلا واحداً من أحصاها دخل الجنة» (البخاري ومسلم). غير أن العلماء اختلفوا في تعداد تلك الأسماء لأن الحديث في الصحيحين لم يذكرها، بل ذِكرها في رواية الترمذي من زيادة راوٍ يناقشها العلماء.", explanation: "يُستفاد منه في باب الأسماء الحسنى عموماً. يُستفاد منه في باب الأسماء الحسنى عموماً مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1726", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "ما معنى اسم الله «الغفار» و«الغفور»؟ وما الفرق بينهما؟", answer: "الغفور: صيغة مبالغة تدل على عِظَم المغفرة وشمولها — أي أنه يغفر الذنب العظيم. الغفار: صيغة مبالغة تدل على تكرار المغفرة ودوامها — أي أنه يغفر مرة بعد مرة. فالغفور يشير إلى الكمية والعِظَم، والغفار يشير إلى التكرار والاستمرار. قال تعالى: ﴿إِنَّهُ كَانَ غَفَّاراً﴾ (نوح: 10) وقال: ﴿وَهُوَ الْغَفُورُ الرَّحِيمُ﴾.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1727", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما معنى اسم الله «القيوم»؟ وما دلالته الاعتقادية؟", answer: "القيوم: من قام يقوم — صيغة مبالغة تجمع معنيين: 1) القائم بنفسه: أي الغني عن كل شيء الذي لا يحتاج لأحد في وجوده. 2) المُقيم لغيره: أي الذي يقوم على كل مخلوق فيحفظه ويرزقه ويُدبّره. الدلالة الاعتقادية: استقلال الله التام عن خلقه، وحاجة المخلوقات جميعاً إليه. ولذا جُمع مع «الحي» في آية الكرسي: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1728", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "كم عدد أسماء الله الحسنى المذكورة في الحديث النبوي الشريف؟", answer: "تسعة وتسعون (99) اسماً، وردت في حديث أبي هريرة أن النبي ﷺ قال: «إن لله تسعة وتسعين اسماً من أحصاها دخل الجنة»، والمقصود بـ«الإحصاء» معرفتها وحفظها والتعبد لله بمعانيها.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1729", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "ما معنى اسم الله «الرحمن» لغةً واصطلاحاً؟", answer: "الرحمن مشتق من الرحمة، وهو من أبنية المبالغة على وزن فَعْلان مما يدل على السعة والامتلاء، أي ذو الرحمة الواسعة الشاملة لجميع الخلق في الدنيا. واسم الرحمن خاص بالله لا يُطلق على غيره، بخلاف الرحيم الذي وُصف به بعض الناس.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1730", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما الفرق بين اسمَي الله «العزيز» و«القوي»؟", answer: "العزيز: ذو العزة الكاملة، غير المغلوب، الذي يعتز به كل شيء ويحتاج إليه كل شيء. القوي: ذو القوة التامة التي لا تنقص ولا تعتريها غلبة. العزة تتضمن معنى الامتناع وعدم الانكسار، بينما القوة تتضمن الاقتدار والمَكنة.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1731", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما اسم الله الذي يدل على أنه الوحيد المستحق للعبادة؟", answer: "اسم «الإله» أو «الله» بالعلمية. أما في أسماء الله الحسنى: «الواحد» و«الأحد» يدلان على انفراده بالوحدانية. الواحد: المنفرد الذي لا نظير له. الأحد: المنفرد الذي لا يقبل الانقسام ولا الشركة في أي وجه.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1732", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "صعب", question: "ما الفرق بين «الحكيم» و«العليم» من أسماء الله الحسنى؟", answer: "العليم: ذو العلم الشامل بكل شيء ظاهراً وباطناً، ماضياً وحاضراً ومستقبلاً، لا يخفى عليه مثقال ذرة. الحكيم: ذو الحكمة في كل أفعاله وأقواله وأقداره، بمعنى إتقان الأشياء وإحكامها ووضعها في مواضعها اللائقة. فالعلم يتعلق بالمعرفة، والحكمة بحُسن التصرف.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1733", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "صعب", question: "من العلماء الذين ألّفوا كتباً مستقلة في شرح أسماء الله الحسنى؟", answer: "أبرز من ألّف في الأسماء الحسنى: ابن القيم في «مدارج السالكين» وكتابه المستقل «شفاء العليل» وبدائع الفوائد. والبيهقي في «الأسماء والصفات». وابن منده في «التوحيد». والرازي في «لوامع البينات». وفي المعاصرين سعيد حوّى في «الأساس في السنة».", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1734", section: "السيرة", category: "الدعوة", level: "متوسط", question: "في أي غار نزل الوحي أول مرة؟", answer: "غار حراء — في جبل النور بالقرب من مكة، وفيّه نزل الوحي أول مرة على النبي ﷺ.", explanation: "يُستفاد منه في باب الدعوة. يُستفاد منه في باب الدعوة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1735", section: "السيرة", category: "الدعوة", level: "متوسط", question: "من أول من آمن من النساء؟", answer: "خديجة بنت خويلد رضي الله عنها — أول من آمن من النساء، وأول زوجة للنبي ﷺ.", explanation: "يُستفاد منه في باب الدعوة. يُستفاد منه في باب الدعوة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1736", section: "السيرة", category: "الهجرة", level: "متوسط", question: "إلى أي مدينة هاجر النبي ﷺ؟", answer: "المدينة المنورة — المدينة التي هاجر إليها النبي ﷺ من مكة، وسُميت يومئذٍ يثرب.", explanation: "يُستفاد منه في باب الهجرة. يُستفاد منه في باب الهجرة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1737", section: "السيرة", category: "الهجرة", level: "متوسط", question: "من صاحب النبي ﷺ في الهجرة؟", answer: "أبو بكر الصديق رضي الله عنه — صاحب النبي ﷺ في الهجرة، وكان معه في الغار.", explanation: "يُستفاد منه في باب الهجرة. يُستفاد منه في باب الهجرة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1738", section: "السيرة", category: "المساجد", level: "متوسط", question: "ما أول مسجد أسسه النبي ﷺ بعد الهجرة؟", answer: "مسجد قباء — أول مسجد أسسه النبي ﷺ بعد الهجرة، وبُني قبل مسجد قباء في المدينة.", explanation: "يُستفاد منه في باب المساجد. يُستفاد منه في باب المساجد مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1739", section: "السيرة", category: "الغزوات", level: "متوسط", question: "ما أول غزوة كبرى في الإسلام؟", answer: "غزوة بدر — أول غزوة كبرى في الإسلام، ووقعت في السنة الثانية للهجرة وانتصر فيها المسلمون.", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1740", section: "السيرة", category: "الغزوات", level: "متوسط", question: "في أي غزوة وقع حفر الخندق؟", answer: "غزوة الخندق — الغزوة التي وُقف فيها الخندق حول المدينة لصدّ تحالف الأحزاب.", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1741", section: "السيرة", category: "الغزوات", level: "متوسط", question: "ما الغزوة التي وقعت في السنة الثالثة للهجرة؟", answer: "غزوة أحد — وقعت في السنة الثالثة للهجرة، وفيها أُصيب النبي ﷺ في وجهه الكريم.", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1742", section: "السيرة", category: "الصلح", level: "متوسط", question: "ما اسم الصلح الذي عقده النبي ﷺ مع قريش؟", answer: "صلح الحديبية — الصلح الذي عقده النبي ﷺ مع قريش في ذي القعدة سنة 6 للهجرة.", explanation: "يُستفاد منه في باب الصلح. يُستفاد منه في باب الصلح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1743", section: "السيرة", category: "الفتح", level: "متوسط", question: "ما الحدث الذي دخل فيه النبي ﷺ مكة فاتحاً؟", answer: "فتح مكة — دخول النبي ﷺ مكة فاتحاً في رمضان سنة 8 للهجرة بلا قتال.", explanation: "يُستفاد منه في باب الفتح. يُستفاد منه في باب الفتح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1744", section: "السيرة", category: "المولد", level: "سهل", question: "في أي عام وُلد النبي محمد ﷺ؟", answer: "عام الفيل، ويوافق سنة 571م على المشهور، وقيل 570م — والمحقَّق أنه عام الفيل، وأما تحريره بالتقويم الميلادي فمحل خلاف بين المؤرخين", explanation: "يُستفاد منه في باب المولد. يُستفاد منه في باب المولد مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1745", section: "السيرة", category: "المولد", level: "متوسط", question: "في أي شهر وأي يوم من الأسبوع وُلد النبي ﷺ؟", answer: "في شهر ربيع الأول، يوم الاثنين؛ لحديث أبي قتادة رضي الله عنه عند مسلم أن النبي ﷺ سُئل عن صوم يوم الاثنين فقال: «ذاك يوم وُلدت فيه». وأما تعيين اليوم من الشهر فمحل خلاف: الثاني عشر هو المشهور، ورجّح جماعة من المتأخرين التاسع", explanation: "يُستفاد منه في باب المولد. يُستفاد منه في باب المولد مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1746", section: "السيرة", category: "الدعوة", level: "سهل", question: "في أي سن بُعث النبي ﷺ؟", answer: "في الأربعين من عمره — السن التي بُعث فيها النبي ﷺ، في غار حراء بجبل النور.", explanation: "يُستفاد منه في باب الدعوة. يُستفاد منه في باب الدعوة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1747", section: "السيرة", category: "الوفاة", level: "متوسط", question: "في أي سنة توفي النبي ﷺ؟", answer: "11هـ / 632م — سنة وفاة النبي ﷺ في المدينة المنورة، ودُفن في حجرة عائشة.", explanation: "يُستفاد منه في باب الوفاة. يُستفاد منه في باب الوفاة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1748", section: "السيرة", category: "الوفاة", level: "متوسط", question: "كم كان عمر النبي ﷺ حين توفي؟", answer: "ثلاث وستون سنة، وهو الثابت في الصحيحين عن عائشة وابن عباس رضي الله عنهم؛ ووردت روايتا «ستين» و«خمس وستين»، وجمع العلماء بينها بترجيح رواية الثلاث والستين، وحمْل رواية الستين على إلغاء الكسر", explanation: "يُستفاد منه في باب الوفاة. يُستفاد منه في باب الوفاة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1749", section: "السيرة", category: "الغزوات", level: "صعب", question: "كم عدد الغزوات التي خرج فيها النبي ﷺ بنفسه؟", answer: "المشهور عند أهل السير والمغازي (كابن إسحاق) سبع وعشرون غزوة، قاتل في تسع منها. وثبت في الصحيحين عن زيد بن أرقم رضي الله عنه أنه غزا تسع عشرة غزوة، وجمع العلماء بأن الاختلاف راجع إلى اختلاف المعدود: فمن عدّ السرايا والمنازل مستقلة كثّر العدد، ومن اقتصر على ما اشتُهر منها غزوةً قلّله", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1750", section: "السيرة", category: "الغزوات", level: "متوسط", question: "في أي غزوة أُصيب النبي ﷺ في وجهه الكريم؟", answer: "غزوة أحد — الغزوة التي أُصيب فيها النبي ﷺ في وجهه الكريم وكسرت رباعيته.", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1751", section: "السيرة", category: "الغزوات", level: "متوسط", question: "من أشار بحفر الخندق في غزوة الأحزاب؟", answer: "سلمان الفارسي رضي الله عنه، كما ذكره ابن إسحاق وأهل المغازي؛ وأصل حفر الخندق ثابت في الصحيحين، وأما تعيين المشير به فمن رواية أهل السير", explanation: "يُستفاد منه في باب الغزوات. يُستفاد منه في باب الغزوات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1752", section: "السيرة", category: "الصلح", level: "متوسط", question: "ما أشهر بنود صلح الحديبية؟", answer: "وضع الحرب عشر سنين، ورجوع المسلمين عامهم ذاك على أن يعتمروا من العام القابل ويقيموا بمكة ثلاثة أيام، وأن يُردّ إلى قريش من أتى النبيَّ ﷺ منهم مسلمًا بغير إذن وليّه ولا يُردّ إلى المسلمين من رجع إلى قريش، وأن من أحبّ أن يدخل في عهد النبي ﷺ أو في عهد قريش دخل فيه — كما في حديث المِسْوَر بن مخرمة ومروان بن الحكم عند البخاري. وعمرة العام القابل هي «عمرة القضاء» لا حجًّا", explanation: "يُستفاد منه في باب الصلح. يُستفاد منه في باب الصلح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1753", section: "السيرة", category: "الدعوة", level: "متوسط", question: "ما اسم عم النبي الذي آذاه ونزلت فيه سورة (تبّت)؟", answer: "أبو لهب عبد العزى — عم النبي ﷺ الذي آذاه، ونزلت فيه سورة المسد (تبّت).", explanation: "يُستفاد منه في باب الدعوة. يُستفاد منه في باب الدعوة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1754", section: "السيرة", category: "الإسراء والمعراج", level: "سهل", question: "ما المسجد الذي أُسري بالنبي إليه؟", answer: "المسجد الأقصى — المسجد الذي أُسري بالنبي ﷺ إليه من مكة في ليلة الإسراء.", explanation: "يُستفاد منه في باب الإسراء والمعراج. يُستفاد منه في باب الإسراء والمعراج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1755", section: "السيرة", category: "الإسراء والمعراج", level: "متوسط", question: "ما الذي فُرض على المسلمين في ليلة الإسراء والمعراج؟", answer: "الصلوات الخمس؛ وقد فُرضت خمسين صلاة ثم خُففت إلى خمس، وفي حديث الإسراء في الصحيحين: «هي خمس وهي خمسون، لا يُبدَّل القول لديّ»", explanation: "يُستفاد منه في باب الإسراء والمعراج. يُستفاد منه في باب الإسراء والمعراج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1756", section: "السيرة", category: "الدعوة", level: "متوسط", question: "ما اسم الدار التي كانت مقراً للدعوة سراً في مكة؟", answer: "دار الأرقم بن أبي الأرقم — مقر الدعوة السرية في مكة قبل الهجرة.", explanation: "يُستفاد منه في باب الدعوة. يُستفاد منه في باب الدعوة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1757", section: "السيرة", category: "المولد والنشأة", level: "سهل", question: "في أي عام وُلد النبي ﷺ؟", answer: "عام الفيل (570م تقريباً) — عام ولادة النبي ﷺ، حين أراد أبرهة هدم الكعبة.", explanation: "يُستفاد منه في باب المولد والنشأة. يُستفاد منه في باب المولد والنشأة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1758", section: "السيرة", category: "المولد والنشأة", level: "سهل", question: "من والد النبي ﷺ؟", answer: "عبدالله بن عبد المطلب — والد النبي ﷺ، توفي قبل مولده بأشهر.  — يُستفاد منه في باب المولد والنشأة مع الرجوع إلى مراجع مجالس العلم.", explanation: "يُستفاد منه في باب المولد والنشأة. يُستفاد منه في باب المولد والنشأة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1759", section: "السيرة", category: "المولد والنشأة", level: "سهل", question: "من والدة النبي ﷺ؟", answer: "آمنة بنت وهب — والدة النبي ﷺ، توفيت وهو ابن ست سنوات في الأبواء.", explanation: "يُستفاد منه في باب المولد والنشأة. يُستفاد منه في باب المولد والنشأة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1760", section: "السيرة", category: "المولد والنشأة", level: "متوسط", question: "من مرضعة النبي ﷺ؟", answer: "حليمة بنت أبي ذؤيب السعدية في بني سعد، وقد أرضعته قبلها ثويبة مولاة أبي لهب أياماً", explanation: "يُستفاد منه في باب المولد والنشأة. يُستفاد منه في باب المولد والنشأة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1761", section: "السيرة", category: "المولد والنشأة", level: "متوسط", question: "ما اسم قبيلة النبي ﷺ؟", answer: "قريش، وهو ﷺ من بني هاشم وهم بطن من بطونها — نسب النبي ﷺ إلى قبيلة قريش.", explanation: "يُستفاد منه في باب المولد والنشأة. يُستفاد منه في باب المولد والنشأة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1762", section: "السيرة", category: "البعثة", level: "سهل", question: "هل أول ما نزل على النبي ﷺ سورة كاملة؟", answer: "لا؛ أول ما نزل عليه ﷺ صدر سورة العلق خمس آيات لا سورة تامة: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ * خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ * اقْرَأْ وَرَبُّكَ الْأَكْرَمُ * الَّذِي عَلَّمَ بِالْقَلَمِ * عَلَّمَ الْإِنسَانَ مَا لَمْ يَعْلَمْ﴾ (العلق: 1-5)، كما في حديث عائشة رضي الله عنها في بدء الوحي (رواه البخاري في أول صحيحه ومسلم). وأما أول سورة نزلت كاملةً فمختلف فيه بين أهل العلم، وأول ما نزل بعد فترة الوحي صدر سورة المدثر: ﴿يَا أَيُّهَا الْمُدَّثِّرُ﴾ (المدثر: 1)", explanation: "يُستفاد منه في باب البعثة. يُستفاد منه في باب البعثة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1763", section: "السيرة", category: "البعثة", level: "متوسط", question: "أين كان النبي ﷺ حين نزل عليه الوحي أول مرة؟", answer: "في غار حراء بجبل النور قرب مكة، وهو ابن أربعين سنة، كما في حديث عائشة رضي الله عنها في بدء الوحي: «وكان يخلو بغار حراء فيتحنّث فيه» (رواه البخاري ومسلم)", explanation: "يُستفاد منه في باب البعثة. يُستفاد منه في باب البعثة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1764", section: "السيرة", category: "الهجرة", level: "سهل", question: "إلى أين هاجر النبي ﷺ؟", answer: "إلى يثرب التي صارت تُسمّى بعد مقدمه ﷺ: المدينة المنورة، وذلك في السنة الثالثة عشرة من البعثة، وبسنة هجرته هذه جُعل مبدأ التأريخ الهجري في خلافة عمر رضي الله عنه", explanation: "يُستفاد منه في باب الهجرة. يُستفاد منه في باب الهجرة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" }
];

