export const FAWAID_ITEMS = [
  { text: "المؤمن للمؤمن كالبنيان يشد بعضه بعضاً؛ فالتعاون بين المسلمين من أصول الإسلام. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة...............", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "من كان في حاجة أخيه كان الله في حاجته؛ فنصرة المسلم واجبة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة..................................", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "ألا أنبئكم بخير أعمالكم وأزكاها عند مليككم… ذكر الله؛ فهو أخف على اللسان وأثقل في الميزان عند الرحمن. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "الترمذي ٣٣٧٧ — صححه الألباني في صحيح الترغيب", author_name: "سنن الترمذي" },
  { text: "من تعلم العلم ليباهي به العلماء ويجاري به السفهاء ويصرف به وجوه الناس إليه أدخله الله جهنم. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "رواه ابن ماجه (260) والترمذي (2654) — صححه الألباني", author_name: "سنن ابن ماجه" },
  { text: "من أنفق نفقة في سبيل الله كُتبت له بسبعمائة ضعف، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "رواه الترمذي (1625) والنسائي (3186) عن خريم بن فاتك الأسدي — حسّنه الترمذي وصححه الألباني", author_name: "سنن الترمذي" },
  { text: "أفلا يتدبرون القرآن أم على قلوب أقفالها، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما دلّ عليه الكتاب والسنة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "محمد: 24", author_name: "القرآن الكريم" },
  { text: "ما يلفظ من قول إلا لديه رقيب عتيد، وهذا من فوائد العناية بلسان العرب وفهم كلام الله. كما دلّ عليه الكتاب والسنة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "اللغة", source: "ق: 18", author_name: "القرآن الكريم" },
  { text: "من تواضع لله رفعه؛ فالرفعة ثمرة الخفض لله، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "من صلى عليّ صلاة صلى الله عليه بها عشراً، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "خذ من أموالهم صدقة تطهرهم وتزكيهم بها، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما دلّ عليه الكتاب والسنة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "التوبة: 103", author_name: "القرآن الكريم" },
  { text: "الصوم جُنة؛ فإذا كان يوم صوم أحدكم فلا يرفث ولا يجهل، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "الحج مرة في العمر واجب على المستطيع، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "وجوب الحج من آل عمران: 97، وتحديد المرة الواحدة من حديث «الحج مرة، فمن زاد فهو تطوع» — رواه أبو داود (1721) وابن ماجه (2886)، صححه الألباني", author_name: "القرآن الكريم والحديث النبوي" },
  { text: "الصدقة تطفئ الخطيئة كما يطفئ الماء النار، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "الترمذي ٦١٤ — حسّنه الألباني", author_name: "سنن الترمذي" },
  { text: "إن الله رفيق يحب الرفق في الأمر كله، وهذا من آداب الدعوة إلى الله بالحكمة والموعظة الحسنة. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الدعوة", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "تعاهدوا القرآن؛ فوالذي نفسي بيده لهو أشد تفلتاً من الإبل في عقلها، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما ثبت في السنة الصحيحة.", category: "القرآن", source: "رواه البخاري ومسلم", author_name: "صحيح البخاري" },
  { text: "أتدرون ما الغيبة؟ ذكرك أخاك بما يكره، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "الحياء لا يأتي إلا بخير، وهذا من مكارم الأخلاق التي أمر بها الشرع. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "رواه البخاري ومسلم", author_name: "صحيح البخاري" },
  { text: "المرء على دين خليله فلينظر أحدكم من يخالل، وهذا من أصول التربية الإسلامية التي يُنشأ عليها الولد. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "رواه أبو داود — حسنه الألباني", author_name: "سنن أبي داود" },
  { text: "الدعاء بين الأذان والإقامة لا يرد، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "رواه أبو داود والترمذي — صححه الألباني في صحيح الترمذي", author_name: "سنن أبي داود" },
  { text: "من قرأ آية الكرسي دبر كل صلاة لم يمنعه من دخول الجنة إلا أن يموت، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما ثبت في السنة الصحيحة.", category: "القرآن", source: "رواه النسائي — صححه الألباني في السلسلة الصحيحة (972)", author_name: "سنن النسائي" },
  { text: "يريد الله بكم اليسر ولا يريد بكم العسر، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما دلّ عليه الكتاب والسنة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "البقرة: 185", author_name: "القرآن الكريم" },
  { text: "الاستغفار سبب لدفع البلاء ونزول الرحمة، وهذا بيان يُعين على فهم مراد الله في كتابه. كما دلّ عليه الكتاب والسنة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "الأنفال: 33 — تفسير ابن كثير", author_name: "ابن كثير" },
  { text: "الفاتحة أم القرآن وأم الكتاب والسبع المثاني، وهذا بيان يُعين على فهم مراد الله في كتابه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "رواه البخاري", author_name: "صحيح البخاري" },
  { text: "{وَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَّكُمْ} — وراء كل قدر حكمة لا تراها، وهذا بيان يُعين على فهم مراد الله في كتابه. كما دلّ عليه الكتاب والسنة.", category: "التفسير", source: "البقرة: 216", author_name: "القرآن الكريم" },
  { text: "الصبر والشكر مطيتان للإيمان لا يُحمل إلا عليهما، وهذا بيان يُعين على فهم مراد الله في كتابه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "مدارج السالكين — فصل منزلة الصبر", author_name: "ابن قيم الجوزية" }
];
